import json,collections,sys,re,glob
sys.stdout.reconfigure(encoding='utf-8')
S=sys.argv[1]
idx=json.load(open("pipeline/_work/run_wol2/index/index.json",encoding="utf-8"))
import csv
cov={r['type']:r for r in csv.DictReader(open("pipeline/_work/run_wol2/reaudit/coverage/coverage.csv",encoding="utf-8"))}
spec="\n".join(open(f,encoding="utf-8").read() for f in glob.glob("C:/visual projects/wol-study/docs/spec/*.md")).lower()
byid={t['id']:t for t in idx['types']}
child=collections.Counter()
for t in idx['types']:
    if t.get('parent') in byid: child[t['parent']]+=t['line_end']-t['line_start']+1
def snake(n): return re.sub(r'([a-z0-9])([A-Z])',r'\1_\2',n).lower()
def mentioned(name):
    seg=name.split('.')[-1]
    cands={seg}
    for suf in('State','Projectile','Emitter'):
        if seg.endswith(suf) and len(seg)>len(suf)+3: cands.add(seg[:-len(suf)])
    for c in cands:
        if len(c)>=5 and (c.lower() in spec or snake(c) in spec): return True
    return False
skip={'items','decor','lib','debug','art','engine'}
rows=[]
for t in idx['types']:
    c=cov.get(t['name'],{})
    rows.append(dict(id=t['id'],file=t['file'],bucket=c.get('bucket','?'),system=c.get('system','?'),kind=t['kind'],own=t['line_end']-t['line_start']+1-child.get(t['id'],0),men=mentioned(t['id']),base=t.get('base_name')))
tot=collections.defaultdict(lambda:[0,0,0,0])
for r in rows:
    if r['bucket'] in skip: continue
    x=tot[r['bucket']]; x[0]+=1; x[1]+=r['own']; x[2]+=r['men']; x[3]+=r['own'] if r['men'] else 0
T=sum(v[1] for v in tot.values()); M=sum(v[3] for v in tot.values())
print("behaviour: types",sum(v[0] for v in tot.values()),"men",sum(v[2] for v in tot.values()),"lines",T,"men lines",M,M/T)
for k,v in sorted(tot.items(),key=lambda kv:-(kv[1][1]-kv[1][3])): print(k,v,"unmentioned lines",v[1]-v[3])
json.dump(rows,open(S+"/rows2.json","w",encoding="utf-8"),ensure_ascii=False)
# group by file
fg=collections.defaultdict(lambda:[0,0,[]])
for r in rows:
    if r['bucket'] in skip or r['men'] or r['kind']=='enum': continue
    f=fg[r['file']]; f[0]+=1; f[1]+=r['own']; f[2].append(r['id'])
print()
for k,v in sorted(fg.items(),key=lambda kv:-kv[1][1])[:45]: print(v[1],v[0],k,[cov.get(i.split('.')[0],{}).get('bucket') for i in v[2][:1]],[i.split('.')[-1] for i in v[2][:4]])
E
python -I $S/gap4.py "$S"

